/** Hand-reviewed scopes. Rebuild JSONL and the complete decision ledger with problems:build:wang. */
import type { OpenProblem } from "../../lib/open-problems.ts";

export const wangSource = {
  author: "Shao-Jiang Wang",
  title: "100 Sharply Formulated Open Problems in Theoretical Physics",
  url: "https://wangshaojiang.wordpress.com/2026/09/02/100-open-problems-in-theoretical-physics/",
  published_on: "2026-09-02",
  status_as_of: "2026-08-31",
  checked_on: "2026-11-18",
  html_sha256: "7665b4eafe9d7957bd2f14b8cce1d18b4da9293cf734d89d2e864c6aec83cd3f",
  assessment: "Named-author, explicitly AI-assisted discovery catalogue. Scope and overlap checked; this is not a comprehensive current-literature or proof audit. New text is editorially reformulated; no reuse license for the source article is asserted.",
};

export interface WangDecision {
  number: number;
  source_title: string;
  decision: "include" | "duplicate" | "review_hold";
  reason: string;
  canonical_id?: string;
  evidence_urls?: string[];
  proposal?: Omit<OpenProblem, "sources">;
  reference_leads?: string[];
}

const constructions = new Set([6, 11, 16, 17, 19, 29, 30, 35, 36, 40, 55]);
function add(number: number, title: string, id: string, area: string, statement: string, assumptions: string[], target: string, motivation: string, status: string, related: string[] = [], refs: string[] = []): WangDecision {
  return {
    number, source_title: title, decision: "include",
    reason: "Distinct theoretical/computational target after comparing model, regime and resolution criterion with the public catalogue and review holds.",
    reference_leads: refs.map(id => `https://arxiv.org/abs/${id}`),
    proposal: {
      schema_version: 1, id, title, aliases: [], domain: "theoretical_physics",
      kind: constructions.has(number) ? "construction_problem" : "open_question",
      primary_area: area, tags: [area, "wang_2026_research_target"],
      statement, assumptions, physics_motivation: motivation, resolution_target: target,
      formulation: "needs_framework", status: "provisionally_open",
      status_note: `${status} Wang's catalogue dates its status assessment to 2026-08-31. Theoria checked the source entry and catalogue overlap; the complete literature and any proofs have not been independently audited. Fix the remaining model choices before using this research target as a theorem benchmark.`,
      review_level: "preliminary_source_check", compiled_on: wangSource.checked_on,
      relations: related.map(id => ({ id, type: "related_to", note: "Related physical setting; the requested model, limit or conclusion differs. This is not an equivalence claim." })),
    },
  };
}
function duplicate(number: number, title: string, canonical_id: string, reason: string): WangDecision {
  return { number, source_title: title, decision: "duplicate", canonical_id, reason };
}
function hold(number: number, title: string, reason: string, evidence_urls: string[] = []): WangDecision {
  return { number, source_title: title, decision: "review_hold", reason, evidence_urls };
}

